def transform(grid):
    """Recolor complete 4-valued horizontal and vertical divider lines to 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    full_rows = {r for r in range(h) if all(v == 4 for v in grid[r])}
    full_cols = {c for c in range(w) if all(grid[r][c] == 4 for r in range(h))}
    for r in range(h):
        for c in range(w):
            if r in full_rows or c in full_cols:
                out[r][c] = 2
    return out

